import{_ as e,o as a,c as t,ao as i}from"./chunks/framework.ucUddl5u.js";const k=JSON.parse('{"title":"Agents messaging each other","description":"","frontmatter":{},"headers":[],"relativePath":"guide/messaging.md","filePath":"guide/messaging.md","lastUpdated":null}'),n={name:"guide/messaging.md"};function o(h,s,r,l,d,c){return a(),t("div",null,[...s[0]||(s[0]=[i(`<h1 id="Agents-messaging-each-other" tabindex="-1">Agents messaging each other <a class="header-anchor" href="#Agents-messaging-each-other" aria-label="Permalink to &quot;Agents messaging each other {#Agents-messaging-each-other}&quot;">​</a></h1><p>Sessions talk to each other. An agent working on your package can ask the agent working on its dependency a question, a worktree session can report back to its parent, and a session on a GPU server can tell the one on your laptop that a run finished. This is the <strong>comm relay</strong>; the agents use it through the bundled skills, and you can use the same scripts from any shell.</p><h2 id="Every-session-joins-at-start" tabindex="-1">Every session joins at start <a class="header-anchor" href="#Every-session-joins-at-start" aria-label="Permalink to &quot;Every session joins at start {#Every-session-joins-at-start}&quot;">​</a></h2><p>A Claude Code or Codex session created in Sessions mode runs <code>/sot-session-start</code> once: it joins the registry under a <strong>handle</strong> — its row&#39;s name — and starts listening. From then on the session is addressable as <code>@&lt;handle&gt;</code> from any other session, on any connected host.</p><h2 id="Ask,-tell,-broadcast" tabindex="-1">Ask, tell, broadcast <a class="header-anchor" href="#Ask,-tell,-broadcast" aria-label="Permalink to &quot;Ask, tell, broadcast {#Ask,-tell,-broadcast}&quot;">​</a></h2><p>The agents call these for you when you say &quot;ask the kernel session whether…&quot;, but they are plain scripts in <code>~/.sot-comm/bin</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">comm-list.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                 # who is reachable, and their state</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">comm-relay.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> send</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @other-session</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;message&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # fire-and-forget</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">comm-relay.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ask</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  @other-session</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;question?&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 60</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # send, then print replies for 60 s</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">comm-relay.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> send</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;message&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # broadcast to every session</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">comm-poll.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                 # catch up on anything that arrived while you were away</span></span></code></pre></div><p><code>send</code> and <code>ask</code> go through the Ship of Tools daemon for live delivery; a session that was away catches up with <code>comm-poll.sh</code>. On arrival, the recipient&#39;s listener files each message into its inbox (<code>~/.sot-comm/inbox/&lt;handle&gt;.jsonl</code>), so a session that was busy reads it with <code>comm-poll.sh</code> when it gets to it.</p><h2 id="A-message-wakes-the-recipient" tabindex="-1">A message wakes the recipient <a class="header-anchor" href="#A-message-wakes-the-recipient" aria-label="Permalink to &quot;A message wakes the recipient {#A-message-wakes-the-recipient}&quot;">​</a></h2><p>An idle session does not have to be polling. When a message lands for a session at its prompt, it is typed into that session&#39;s row. A Codex session gets each message&#39;s full text. A Claude Code session gets one short wake line and reads the messages itself with <code>comm-poll.sh</code>, so a burst of messages costs one wake. The wake is refused while the row shows a permission dialog or a menu, so it can never answer one by accident.</p><h2 id="What-travels-with-it" tabindex="-1">What travels with it <a class="header-anchor" href="#What-travels-with-it" aria-label="Permalink to &quot;What travels with it {#What-travels-with-it}&quot;">​</a></h2><p>The same registry that routes messages carries each session&#39;s work state (working, question, waiting, done, idle), which is what colours the rows in Sessions mode. See <a href="./../concepts/work-state">Work-state colours</a> and, for the wire format and the registry layout, <a href="./../concepts/comm">The comm relay</a> and the <a href="./../ref/comm">Comm protocol</a> reference.</p>`,12)])])}const g=e(n,[["render",o]]);export{k as __pageData,g as default};
